-- Entasis Academy, migration 3 : le catalogue seme.
--
-- Douze modules (trois microlecons, un cas pratique, dix questions corrigees
-- chacun) et trois parcours qui les reutilisent sans les dupliquer. Genere
-- par scripts/academy/generer-seed.mjs depuis scripts/academy/catalogue/*.json :
-- ne pas editer ce fichier a la main, regenerer.
--
-- Contenu redige par des redacteurs puis verifie a la source officielle
-- (impots.gouv.fr, service-public.fr, legifrance, AMF, ameli...), les
-- procedures internes remplacees par « [a completer par le cabinet] », les cas
-- fictifs etiquetes. Tout est seme en BROUILLON : la publication est un geste
-- de l administrateur qui enregistre le nom du relecteur.
--
-- Idempotent : un module dont le slug existe est ignore (where not exists),
-- jamais mis a jour ; un parcours existant garde ses modules. Relancer ne
-- duplique rien et n ecrase aucune edition de l administrateur.
--
-- Appliquee sur entasis-crm-DEV (leuqchrianpasianwmjg) le 21 septembre
-- 2026, puis EN PRODUCTION le meme jour apres accord de Louis, un fichier
-- par migration (noms academy_3_seed_01 a _13 dans schema_migrations,
-- versions 20260921131206 a 20260921133002), contenu verifie au md5.
-- Cet en tete a ete mis a jour apres l application : le md5 des fichiers
-- ne correspond plus a celui des statements enregistres, le corps est
-- identique.

-- ── Module 11 : Qualité du dossier et vigilance (qualite-du-dossier) ──
do $seed_qualite_du_dossier$
declare v_mod uuid; v_ver uuid; v_l1 uuid; v_l2 uuid; v_l3 uuid; v_q uuid; v_lecon uuid;
begin
  if exists (select 1 from public.academy_modules where slug = $academy_seed$qualite-du-dossier$academy_seed$) then
    return;
  end if;
  insert into public.academy_modules (slug, titre, theme, niveau, ordre)
  values ($academy_seed$qualite-du-dossier$academy_seed$, $academy_seed$Qualité du dossier et vigilance$academy_seed$, $academy_seed$methode$academy_seed$, $academy_seed$fondamentaux$academy_seed$, 11)
  returning id into v_mod;
  insert into public.academy_module_versions (module_id, numero, statut, titre, objectif, competence, duree_minutes, prerequis, seuil_reussite, cas_pratique, a_completer, sources, fictif)
  values (v_mod, 1, 'brouillon', $academy_seed$Qualité du dossier et vigilance$academy_seed$, $academy_seed$À la fin du module, le conseiller sait lister les pièces qui manquent à un dossier avant toute recommandation, repérer et documenter une incohérence entre ce que le client déclare, ce que les pièces montrent et ce que le projet suppose, et décider quand un dossier doit être suspendu et remonté au responsable désigné, sans jamais en informer le client.$academy_seed$, $academy_seed$Identifier pièces manquantes, incohérences et besoin d'escalade$academy_seed$, 15, $academy_seed$["reussir-la-decouverte"]$academy_seed$::jsonb, 0.80,
          $academy_seed${"titre":"Le dossier repris d'un collègue parti","situation_markdown":"Cas fictif. Vous reprenez le dossier de Monsieur Raphaël Andrieu, 47 ans, transmis par un collègue qui a quitté le cabinet. Le client vous relance par courriel : il souhaite « signer cette semaine ».\n\nLa fiche CRM indique : chirurgien-dentiste, revenus annuels 140 000 euros, marié, deux enfants, objectif « préparer la retraite », horizon quinze ans, profil équilibré. Une note du collègue précise : « client pressé, veut tout placer avant la fin du mois, PER et assurance vie, achat immobilier prévu l'an prochain, détient déjà un portefeuille titres chez une banque en ligne ».\n\nLes pièces au dossier : une carte d'identité expirée depuis quatre mois ; un avis d'imposition de l'année précédente qui mentionne 92 000 euros de revenus et une situation de célibataire ; un relevé de compte montrant 310 000 euros arrivés il y a cinq semaines par virement d'une SCI dont le nom ne figure nulle part dans la fiche ; un questionnaire connaissance et expérience signé, dont la case « expérience en instruments financiers » indique « aucune ».\n\nIl n'y a ni justificatif de domicile, ni pièce sur l'origine des 310 000 euros, ni lettre de mission signée. Le montant que le client veut placer est de 300 000 euros.","questions":["Listez les pièces manquantes ou à renouveler avant toute recommandation.","Relevez les incohérences du dossier et classez chacune : erreur probable, point à questionner, signal d'alerte.","Que faites-vous avant de répondre au courriel du client, et qui informez-vous ?","Qu'est-ce que vous ne faites surtout pas dans cette situation ?"],"corrige_markdown":"## 1. Pièces manquantes ou à renouveler\n\n- Pièce d'identité en cours de validité (l'actuelle est expirée : la vérification d'identité doit reposer sur un document probant valide).\n- Justificatif de domicile récent.\n- Justificatif de l'origine des 310 000 euros : nature du lien avec la SCI, acte ou décision expliquant le virement (cession de parts, distribution, remboursement de compte courant), avec la pièce correspondante.\n- Avis d'imposition le plus récent, pour actualiser revenus et situation familiale.\n- Lettre de mission signée avant tout conseil.\n- Selon la procédure interne, questionnaire mis à jour et classification du risque du client [a completer par le cabinet].\n\nTant que l'identité vérifiée, l'origine des fonds et l'objet de la relation ne sont pas documentés, aucune opération ne peut être exécutée (leçon 1, article L561-8).\n\n## 2. Incohérences et classement\n\n- Revenus : 140 000 euros dans la fiche contre 92 000 euros sur l'avis. Point à questionner : l'avis est antérieur, les revenus ont pu évoluer, mais l'écart est important et doit être expliqué par une pièce récente.\n- Situation familiale : marié deux enfants dans la fiche, célibataire sur l'avis. Erreur probable ou changement récent : à vérifier, car cela change la fiscalité et la clause bénéficiaire.\n- Expérience : « aucune » dans le questionnaire, portefeuille titres dans la note. Point à questionner : le questionnaire signé ne reflète pas la réalité, il doit être repris avec le client, pas corrigé seul.\n- Horizon : « retraite, quinze ans » contre achat immobilier l'an prochain et volonté de « tout placer ». Point à questionner, prioritaire : placer 300 000 euros dans des enveloppes peu disponibles alors qu'un achat est prévu à douze mois contredit l'objectif de vie.\n- Origine des fonds : 310 000 euros d'une SCI inconnue du dossier, cinq semaines avant, client pressé. Signal d'alerte : montant inhabituellement élevé au regard des revenus connus, sans justification documentée, avec une pression sur le calendrier. C'est le cas typique d'examen renforcé (leçon 3, article L561-10-2).\n\n## 3. Avant de répondre au courriel\n\n- Ne rien promettre sur un calendrier de signature.\n- Rédiger la liste des pièces et des questions ouvertes dans le CRM, avec la date.\n- Informer par écrit le responsable désigné [a completer par le cabinet] du signal sur l'origine des fonds, avec les faits observés : montant, provenance, délai, absence de pièce, pression du client. Sans qualification.\n- Répondre au client sur un ton neutre : le dossier est repris, un rendez-vous d'actualisation est nécessaire, voici les pièces à préparer. Si le responsable demande de suspendre tout contact, s'y tenir.\n- Prévoir un rendez-vous de découverte complémentaire pour reprendre revenus, situation familiale, expérience, horizon et projet immobilier (module « Réussir la découverte »).\n\n## 4. Ce qu'on ne fait surtout pas\n\n- Signer « pour ne pas perdre le client » en prévoyant de compléter les pièces ensuite.\n- Corriger soi-même la fiche pour la rendre cohérente (revenus, expérience, situation).\n- Considérer que le collègue parti « avait sûrement vérifié ».\n- Dire au client qu'un doute existe sur l'origine de ses fonds ou qu'un signalement pourrait être fait : l'existence d'une déclaration ne se révèle jamais (article L561-18).\n- Escalader oralement sans trace écrite."}$academy_seed$::jsonb, $academy_seed$["Liste officielle des pièces exigées par le cabinet à l'entrée en relation (personne physique, personne morale) et durée de validité acceptée pour chaque pièce (justificatif de domicile, extrait d'immatriculation, avis d'imposition).","Nom du déclarant Tracfin et du correspondant Tracfin désignés au sein du cabinet, et circuit interne de remontée d'un dossier douteux (à qui, par quel canal, sous quel délai).","Procédure d'examen renforcé : qui décide de suspendre une opération, où sont consignées les questions posées au client et leurs réponses.","Fréquence et modalités d'actualisation des dossiers clients selon le niveau de risque retenu par la cartographie du cabinet.","Méthode de classification du risque LCB-FT de chaque client (critères, grille, où elle est enregistrée dans le CRM).","Emplacement de stockage des pièces dans le CRM et règle de nommage et de datation.","Modèle de courriel de demande de pièces et de liste de pièces remis au client après le premier entretien.","Règle de reprise d'un dossier transmis par un conseiller qui a quitté le cabinet : qui valide la reprise, quelle revue de complétude est exigée avant tout nouveau conseil.","Contenu et fréquence de la formation interne LCB-FT suivie par les conseillers, et justificatifs conservés.","Utilisation ou non de la tolérance du IV de l'article L561-5 (vérification d'identité achevée pendant l'établissement de la relation en cas de risque faible) : cas admis, qui décide, comment la trace est conservée."]$academy_seed$::jsonb, $academy_seed$[{"titre":"Code monétaire et financier, article L561-5 (identification et vérification de l'identité du client)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000033517742","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur consultée le 2026-09-21","ce_qu_elle_etablit":"Avant d'entrer en relation d'affaires, la personne assujettie identifie le client et le bénéficiaire effectif et vérifie leur identité sur présentation de tout document écrit à caractère probant."},{"titre":"Code monétaire et financier, article L561-5-1 (connaissance de l'objet et de la nature de la relation)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000033512858","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur consultée le 2026-09-21","ce_qu_elle_etablit":"Avant d'entrer en relation, la personne assujettie recueille les informations relatives à l'objet et à la nature de la relation d'affaires."},{"titre":"Code monétaire et financier, article L561-8 (impossibilité de satisfaire aux obligations d'identification)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000041577826","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur au 14 février 2020","ce_qu_elle_etablit":"Si les obligations des articles L561-5 ou L561-5-1 ne peuvent être satisfaites, la personne assujettie n'exécute aucune opération, n'établit ni ne poursuit aucune relation d'affaires, et peut effectuer une déclaration à Tracfin."},{"titre":"Synthèse des constats des contrôles de l'AMF en matière de LCB-FT ayant donné lieu à des suites entre 2022 et 2025","url":"https://www.amf-france.org/sites/institutionnel/files/private/2026-06/Synth%C3%A8se%20des%20contr%C3%B4les%20AMF%20en%20mati%C3%A8re%20de%20LCB-FT%20et%20d%E2%80%99EAI%20(2022-2025)_1.pdf","emetteur":"AMF","date_consultation":"2026-09-21","date_validite":"juin 2026","ce_qu_elle_etablit":"Manquements récurrents : dossiers sans pièce d'identité, justificatif de domicile, bulletin de souscription, origine des fonds, extrait d'immatriculation récent ou éléments sur les bénéficiaires effectifs ; pièces établies tardivement ne régularisant pas l'insuffisance initiale ; l'ancienneté de la relation ne dispense pas de l'actualisation."},{"titre":"Position-recommandation AMF DOC-2019-16, lignes directrices sur les obligations de vigilance à l'égard des clients et de leurs bénéficiaires effectifs","url":"https://www.amf-france.org/en/regulation/policy/doc-2019-16","emetteur":"AMF","date_consultation":"2026-09-21","date_validite":"publiée le 29 novembre 2019, mise à jour le 2 octobre 2023","ce_qu_elle_etablit":"Applicable aux CIF : identification et vérification de l'identité par document probant, connaissance de la relation d'affaires, recommandation de s'assurer de la conformité et de l'actualisation des dossiers clients quelle que soit l'ancienneté du client."},{"titre":"Code monétaire et financier, article L561-6 (vigilance constante et examen attentif des opérations)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000033517733","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur au 3 décembre 2016","ce_qu_elle_etablit":"Pendant toute la relation d'affaires, la personne assujettie exerce une vigilance constante et pratique un examen attentif des opérations, en veillant à leur cohérence avec la connaissance actualisée de la relation d'affaires."},{"titre":"Position AMF DOC-2019-03, exigences d'adéquation de la directive MiFID II","url":"https://www.amf-france.org/fr/reglementation/doctrine/doc-2019-03","emetteur":"AMF","date_consultation":"2026-09-21","date_validite":"version applicable depuis le 3 octobre 2023","ce_qu_elle_etablit":"Position applicable aux prestataires de services d'investissement, qui intègre les orientations ESMA révisées sur l'adéquation (ESMA35-43-3172) : mesures raisonnables pour vérifier la fiabilité des informations recueillies auprès des clients et mise à jour de ces informations. L'AMF a étendu ces orientations révisées aux CIF via la mise à jour de la position-recommandation DOC-2006-23 (annonce du 12 juin 2023, entrée en vigueur le 3 octobre 2023)."},{"titre":"Code monétaire et financier, article L561-10-2 (examen renforcé des opérations complexes ou inhabituelles)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000033517652","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur au 3 décembre 2016","ce_qu_elle_etablit":"Examen renforcé de toute opération particulièrement complexe, d'un montant inhabituellement élevé ou sans justification économique ou objet licite apparent ; le cabinet se renseigne sur l'origine et la destination des fonds, l'objet de l'opération et le bénéficiaire."},{"titre":"Code monétaire et financier, article L561-10 (mesures de vigilance complémentaires)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000041577809","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur au 24 décembre 2025","ce_qu_elle_etablit":"Vigilance complémentaire pour les personnes politiquement exposées, les produits ou opérations favorisant l'anonymat et les opérations avec des pays à haut risque."},{"titre":"Code monétaire et financier, article L561-15 (déclaration de soupçon à Tracfin)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000033517847","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur au 3 décembre 2016","ce_qu_elle_etablit":"Obligation de déclarer les sommes ou opérations dont on sait, soupçonne ou a de bonnes raisons de soupçonner qu'elles proviennent d'une infraction punie de plus d'un an d'emprisonnement, ou de fraude fiscale selon des critères fixés par décret."},{"titre":"Code monétaire et financier, section 4, article L561-18 (confidentialité de la déclaration)","url":"https://www.legifrance.gouv.fr/codes/section_lc/LEGITEXT000006072026/LEGISCTA000020180500/","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur au 1er juin 2019","ce_qu_elle_etablit":"La déclaration à Tracfin est confidentielle ; il est interdit d'en révéler l'existence, le contenu ou les suites au propriétaire des fonds ou à des tiers non autorisés."},{"titre":"Code monétaire et financier, article R561-23 (désignation des personnes habilitées à déclarer à Tracfin)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000041592391","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur consultée le 2026-09-21","ce_qu_elle_etablit":"Les personnes assujetties, dont les conseillers en investissements financiers, communiquent à Tracfin et à leur autorité de contrôle l'identité de leurs dirigeants ou préposés habilités à procéder aux déclarations de soupçon ; la déclaration relève donc d'une personne habilitée et déclarée, pas d'un conseiller isolé."},{"titre":"FAQ ERMES, plateforme de télédéclaration de Tracfin","url":"https://tracfin.finances.gouv.fr/Pages/Faq.aspx","emetteur":"Tracfin","date_consultation":"2026-09-21","date_validite":"page consultée le 2026-09-21","ce_qu_elle_etablit":"Pour déclarer un soupçon, le professionnel doit préalablement être inscrit sur ERMES en tant que déclarant, ce qui suppose une désignation formelle au sein du cabinet."},{"titre":"Code monétaire et financier, article L574-1 (sanction de la divulgation d'une déclaration de soupçon)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000041578321","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur consultée le 2026-09-21","ce_qu_elle_etablit":"La méconnaissance de l'interdiction de divulgation posée à l'article L561-18 est punie d'une amende de 22 500 euros."}]$academy_seed$::jsonb, false)
  returning id into v_ver;
  insert into public.academy_lecons (version_id, ordre, slug, titre, objectif, duree_minutes, contenu_md, mini_question, mini_reponse, sources)
  values (v_ver, 1, $academy_seed$l1$academy_seed$, $academy_seed$Le dossier complet : ce qui doit s'y trouver$academy_seed$, $academy_seed$Lister les pièces manquantes ou périmées d'un dossier avant d'ouvrir l'étude, en distinguant ce qui bloque l'opération de ce qui peut attendre.$academy_seed$, 4, $academy_seed$## Explication simple

Un dossier n'est pas une pile de documents. C'est la preuve datée que le cabinet connaît la personne qu'il conseille. Le Code monétaire et financier impose d'identifier le client et de vérifier son identité sur un document écrit à caractère probant avant l'entrée en relation (article L561-5), de recueillir l'objet et la nature de la relation (article L561-5-1), puis de tenir cette connaissance à jour pendant toute la relation (article L561-6). Si ces éléments ne peuvent pas être obtenus, le cabinet n'entre pas en relation et n'exécute aucune opération (article L561-8). La loi tolère, à titre exceptionnel et en cas de risque faible, que la vérification se termine pendant l'établissement de la relation (IV de l'article L561-5), mais jamais après une opération, et la procédure du cabinet fixe si cette tolérance est utilisée [a completer par le cabinet].

L'AMF, dans sa synthèse des contrôles publiée en juin 2026, relève que les manquements les plus fréquents sont des dossiers sans pièce d'identité, sans justificatif de domicile, sans élément sur l'origine des fonds, ou avec des documents obsolètes. Elle rappelle qu'une pièce produite après l'opération ne régularise pas l'insuffisance initiale.

Pour un conseiller débutant, la question tient en trois points : avant d'ouvrir l'étude, puis-je prouver qui est cette personne, d'où vient l'argent, et ce qu'elle veut faire ?

Liste type, à ajuster selon la procédure interne [a completer par le cabinet] : pièce d'identité en cours de validité, justificatif de domicile récent, situation familiale et professionnelle, revenus et fiscalité (dernier avis d'imposition), patrimoine détenu, origine des fonds à investir, connaissance et expérience financières, objectifs de vie et horizon, rapport au risque, résidence fiscale, qualité éventuelle de personne politiquement exposée. Pour une société : extrait d'immatriculation récent, statuts et identification des bénéficiaires effectifs.

## Exemple

Cas fictif. Madame Vasseur, 52 ans, orthodontiste, souhaite investir 180 000 euros issus, dit-elle, de la vente d'un appartement. Le conseiller a sa carte d'identité, son avis d'imposition et le questionnaire sur le rapport au risque. Il manque l'acte de vente ou l'attestation notariée qui documente l'origine des fonds, et le justificatif de domicile date de trois ans. Avant de rédiger la moindre feuille de route, le conseiller note ces deux pièces dans le CRM et les demande au prochain échange, en expliquant qu'il s'agit d'une obligation légale commune à tous les cabinets.

## Erreur fréquente

Considérer que la confiance remplace la pièce. « Je la connais depuis dix ans, son cousin est client » ne remplace ni la copie du document d'identité ni la trace datée de sa vérification. L'AMF est explicite : l'ancienneté de la relation ou l'absence apparente de risque ne dispense pas d'un dossier à jour. Autre erreur : lancer la souscription et prévoir de « compléter après ». Le contrôle compare la date des pièces à la date de l'opération.

## En rendez-vous

Annoncer les pièces dès le premier entretien, avec une phrase simple : « Pour pouvoir vous conseiller, nous avons besoin de quelques justificatifs, c'est la même règle pour tout le monde. » Envoyer la liste par écrit après le rendez-vous. Dans le CRM, noter ce qui est reçu, ce qui manque et la date de chaque pièce. Ne pas passer à l'étude tant que l'identité et l'origine des fonds ne sont pas documentées.

## Trois points a retenir

1. Le dossier prouve, il ne raconte pas : chaque information importante s'appuie sur une pièce datée.
2. Identité vérifiée, origine des fonds, objet de la relation : sans ces trois éléments, aucune opération.
3. Une pièce obtenue après l'opération ne répare pas un dossier incomplet au moment de l'opération.$academy_seed$, $academy_seed${"enonce":"Vous avez la pièce d'identité, l'avis d'imposition et le questionnaire sur le rapport au risque. Le client veut souscrire aujourd'hui. Au titre de la vigilance LCB-FT décrite dans la leçon, que vérifiez-vous encore avant d'exécuter la moindre opération ?","choix":["Rien, l'essentiel est réuni","Que l'origine des fonds et l'objet de la relation sont documentés par une pièce","Que le client a bien reçu la plaquette de présentation du cabinet","Que le contrat visé est disponible chez l'assureur"],"explication":"La leçon rappelle les trois éléments sans lesquels le cabinet n'exécute aucune opération : identité vérifiée, origine des fonds, objet de la relation. Le questionnaire risque et l'avis d'imposition ne documentent pas d'où vient l'argent. La plaquette est un document d'information, elle ne documente ni l'identité, ni l'origine des fonds, ni l'objet de la relation.","competence":"Identifier les pièces manquantes"}$academy_seed$::jsonb, 1, $academy_seed$[{"titre":"Code monétaire et financier, article L561-5 (identification et vérification de l'identité du client)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000033517742","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur consultée le 2026-09-21","ce_qu_elle_etablit":"Avant d'entrer en relation d'affaires, la personne assujettie identifie le client et le bénéficiaire effectif et vérifie leur identité sur présentation de tout document écrit à caractère probant."},{"titre":"Code monétaire et financier, article L561-5-1 (connaissance de l'objet et de la nature de la relation)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000033512858","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur consultée le 2026-09-21","ce_qu_elle_etablit":"Avant d'entrer en relation, la personne assujettie recueille les informations relatives à l'objet et à la nature de la relation d'affaires."},{"titre":"Code monétaire et financier, article L561-8 (impossibilité de satisfaire aux obligations d'identification)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000041577826","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur au 14 février 2020","ce_qu_elle_etablit":"Si les obligations des articles L561-5 ou L561-5-1 ne peuvent être satisfaites, la personne assujettie n'exécute aucune opération, n'établit ni ne poursuit aucune relation d'affaires, et peut effectuer une déclaration à Tracfin."},{"titre":"Synthèse des constats des contrôles de l'AMF en matière de LCB-FT ayant donné lieu à des suites entre 2022 et 2025","url":"https://www.amf-france.org/sites/institutionnel/files/private/2026-06/Synth%C3%A8se%20des%20contr%C3%B4les%20AMF%20en%20mati%C3%A8re%20de%20LCB-FT%20et%20d%E2%80%99EAI%20(2022-2025)_1.pdf","emetteur":"AMF","date_consultation":"2026-09-21","date_validite":"juin 2026","ce_qu_elle_etablit":"Manquements récurrents : dossiers sans pièce d'identité, justificatif de domicile, bulletin de souscription, origine des fonds, extrait d'immatriculation récent ou éléments sur les bénéficiaires effectifs ; pièces établies tardivement ne régularisant pas l'insuffisance initiale ; l'ancienneté de la relation ne dispense pas de l'actualisation."},{"titre":"Position-recommandation AMF DOC-2019-16, lignes directrices sur les obligations de vigilance à l'égard des clients et de leurs bénéficiaires effectifs","url":"https://www.amf-france.org/en/regulation/policy/doc-2019-16","emetteur":"AMF","date_consultation":"2026-09-21","date_validite":"publiée le 29 novembre 2019, mise à jour le 2 octobre 2023","ce_qu_elle_etablit":"Applicable aux CIF : identification et vérification de l'identité par document probant, connaissance de la relation d'affaires, recommandation de s'assurer de la conformité et de l'actualisation des dossiers clients quelle que soit l'ancienneté du client."}]$academy_seed$::jsonb)
  returning id into v_l1;
  insert into public.academy_lecons (version_id, ordre, slug, titre, objectif, duree_minutes, contenu_md, mini_question, mini_reponse, sources)
  values (v_ver, 2, $academy_seed$l2$academy_seed$, $academy_seed$Lire les incohérences d'un dossier$academy_seed$, $academy_seed$Repérer une incohérence entre déclarations, pièces et projet, la questionner avec neutralité et documenter la réponse avant toute recommandation.$academy_seed$, 4, $academy_seed$## Explication simple

Un dossier complet peut encore être faux. L'article L561-6 du Code monétaire et financier demande une vigilance constante : les opérations doivent rester cohérentes avec la connaissance actualisée que le cabinet a du client. La position AMF DOC-2019-03 sur les exigences d'adéquation, dont l'AMF applique les principes aux CIF par la position-recommandation DOC-2006-23, ajoute que des mesures raisonnables doivent vérifier la fiabilité des informations recueillies et les tenir à jour.

Concrètement, le conseiller croise trois sources : ce que le client dit, ce que les pièces montrent, ce que le projet suppose. Quatre croisements suffisent dans la plupart des cas :

- revenus déclarés dans le questionnaire contre avis d'imposition ;
- montant à investir contre patrimoine déclaré et origine des fonds documentée ;
- horizon et objectif contre besoin de liquidité (un « placement retraite » avec un achat immobilier dans dix-huit mois) ;
- rapport au risque déclaré contre expérience réelle et réactions observées en rendez-vous.

Une incohérence n'est pas une accusation. Le plus souvent, c'est une erreur de saisie, un oubli ou une information dépassée. Mais elle doit être notée, questionnée et résolue par écrit avant la recommandation, jamais lissée pour que le dossier « passe ».

## Exemple

Cas fictif. Monsieur Lecoq, gérant majoritaire d'une SARL de plomberie, déclare 60 000 euros de revenus annuels dans le questionnaire. Son avis d'imposition indique 38 000 euros. Il veut placer 250 000 euros « d'économies ». Le patrimoine déclaré ne comporte aucun compte de cette taille et aucune cession récente. Trois lectures sont possibles : dividendes non mentionnés, prêt familial, ou origine que le client ne souhaite pas dire. Le conseiller ne tranche pas, il demande : « J'ai un écart entre le questionnaire et votre avis d'imposition, pouvez-vous m'aider à comprendre ? » puis « D'où proviennent précisément ces 250 000 euros ? » Il note la réponse et la pièce qui la prouve.

## Erreur fréquente

Corriger soi-même le chiffre pour rendre le dossier cohérent. Modifier le revenu déclaré pour qu'il colle à l'avis, ou relever le profil de risque pour justifier une allocation déjà envisagée, c'est fabriquer un dossier. Deuxième erreur : poser la question, obtenir une réponse orale rassurante et ne rien écrire. L'AMF rappelle que des échanges informels ne remplacent pas une actualisation formalisée et documentée des informations.

## En rendez-vous

Préparer le rendez-vous en surlignant les écarts dans la fiche. Les aborder avec neutralité, comme un point de méthode, pas comme un soupçon. Reformuler la réponse du client et dire quelle pièce la documentera. Après le rendez-vous, mettre à jour la fiche avec la version corrigée, la date et la source de l'information. Si l'écart persiste sans explication crédible, ou si la réponse soulève une nouvelle question, passer à la leçon 3.

## Trois points a retenir

1. Croiser déclaration, pièce et projet : les trois doivent raconter la même histoire.
2. Une incohérence se questionne et se documente, elle ne se corrige pas en silence.
3. L'explication orale ne compte que si elle est écrite dans la fiche et appuyée par une pièce.$academy_seed$, $academy_seed${"enonce":"Le questionnaire indique 60 000 euros de revenus, l'avis d'imposition 38 000 euros. La bonne pratique consiste à corriger le questionnaire pour l'aligner sur l'avis, puis à poursuivre l'étude.","choix":["Vrai","Faux"],"explication":"Faux. La leçon insiste : une incohérence se questionne auprès du client et la réponse se documente avec la date et la pièce. Corriger soi-même un chiffre pour rendre le dossier cohérent revient à fabriquer le dossier.","competence":"Détecter les incohérences"}$academy_seed$::jsonb, 1, $academy_seed$[{"titre":"Code monétaire et financier, article L561-6 (vigilance constante et examen attentif des opérations)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000033517733","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur au 3 décembre 2016","ce_qu_elle_etablit":"Pendant toute la relation d'affaires, la personne assujettie exerce une vigilance constante et pratique un examen attentif des opérations, en veillant à leur cohérence avec la connaissance actualisée de la relation d'affaires."},{"titre":"Position AMF DOC-2019-03, exigences d'adéquation de la directive MiFID II","url":"https://www.amf-france.org/fr/reglementation/doctrine/doc-2019-03","emetteur":"AMF","date_consultation":"2026-09-21","date_validite":"version applicable depuis le 3 octobre 2023","ce_qu_elle_etablit":"Position applicable aux prestataires de services d'investissement, qui intègre les orientations ESMA révisées sur l'adéquation (ESMA35-43-3172) : mesures raisonnables pour vérifier la fiabilité des informations recueillies auprès des clients et mise à jour de ces informations. L'AMF a étendu ces orientations révisées aux CIF via la mise à jour de la position-recommandation DOC-2006-23 (annonce du 12 juin 2023, entrée en vigueur le 3 octobre 2023)."},{"titre":"Synthèse des constats des contrôles de l'AMF en matière de LCB-FT ayant donné lieu à des suites entre 2022 et 2025","url":"https://www.amf-france.org/sites/institutionnel/files/private/2026-06/Synth%C3%A8se%20des%20contr%C3%B4les%20AMF%20en%20mati%C3%A8re%20de%20LCB-FT%20et%20d%E2%80%99EAI%20(2022-2025)_1.pdf","emetteur":"AMF","date_consultation":"2026-09-21","date_validite":"juin 2026","ce_qu_elle_etablit":"Constats fréquents d'origine des fonds incohérente avec la situation financière du client ; des échanges informels ne se substituent pas à une actualisation formalisée et documentée des informations."}]$academy_seed$::jsonb)
  returning id into v_l2;
  insert into public.academy_lecons (version_id, ordre, slug, titre, objectif, duree_minutes, contenu_md, mini_question, mini_reponse, sources)
  values (v_ver, 3, $academy_seed$l3$academy_seed$, $academy_seed$Savoir s'arrêter et escalader$academy_seed$, $academy_seed$Décider quand suspendre un dossier et le remonter par écrit au responsable désigné, sans exécuter d'opération et sans en informer le client.$academy_seed$, 5, $academy_seed$## Explication simple

Le conseiller n'est jamais seul face à un dossier qui pose problème. Trois niveaux de réaction existent.

Premier niveau : la pièce manquante ou l'écart explicable. Il se règle avec le client, comme vu dans les leçons 1 et 2.

Deuxième niveau : l'opération particulièrement complexe, d'un montant inhabituellement élevé ou sans justification économique apparente. La loi impose alors un examen renforcé : le cabinet se renseigne sur l'origine et la destination des fonds, l'objet de l'opération et l'identité de la personne qui en bénéficie (article L561-10-2). Certains profils appellent aussi une vigilance complémentaire, notamment les personnes politiquement exposées (article L561-10).

Troisième niveau : le soupçon. Quand le cabinet sait, soupçonne ou a de bonnes raisons de soupçonner que des sommes proviennent d'une infraction punie de plus d'un an d'emprisonnement, ou de fraude fiscale selon des critères fixés par décret, il doit déclarer à Tracfin (article L561-15). Cette déclaration est confidentielle : il est interdit d'en révéler l'existence ou le contenu au client ou à un tiers (article L561-18). Elle est effectuée par le dirigeant ou le préposé habilité que le cabinet a déclaré à Tracfin et à l'AMF (article R561-23), jamais par le conseiller de son propre chef [a completer par le cabinet : nom du déclarant Tracfin et circuit interne de remontée].

Tant que le doute n'est pas levé, le cabinet n'entre pas en relation et n'exécute aucune opération (article L561-8). Escalader n'est pas un aveu de faiblesse, c'est la procédure normale d'un cabinet indépendant qui protège ses clients et lui-même.

## Exemple

Cas fictif. Monsieur Tavares, 34 ans, se présente comme consultant indépendant, sans site ni clients identifiables. Il souhaite verser 400 000 euros sur un contrat, en trois virements depuis deux banques dont une à l'étranger. Il refuse de préciser l'origine des fonds : « ce sont mes affaires ». Aucune pièce ne documente une activité générant un tel montant. Le conseiller ne fait rien signer, ne promet rien, remercie et clôt le rendez-vous. Le jour même, il remonte le dossier par écrit au responsable désigné, avec les faits observés, sans qualification ni interprétation. Il ne dit pas au client qu'un signalement est envisagé.

## Erreur fréquente

Deux extrêmes. Le premier : avancer quand même parce que l'opération compte pour le mois, en se disant que la compagnie fera ses propres contrôles. Le cabinet a sa propre obligation, elle ne se délègue pas. Le second : prévenir le client « par honnêteté » qu'un doute existe et qu'une déclaration pourrait suivre. C'est une infraction pénale (article L574-1). Une troisième erreur, plus discrète : escalader oralement dans le couloir, sans trace. Une escalade se fait par écrit, datée, avec les faits.

## En rendez-vous

Garder un ton calme et factuel. Ne pas argumenter, ne pas menacer, ne pas rassurer à tort. Une phrase suffit : « Je dois vérifier quelques éléments de mon côté avant de vous répondre, je reviens vers vous. » Ne rien faire signer. Après le rendez-vous, noter les faits dans le CRM tels qu'observés, puis transmettre au responsable selon la procédure [a completer par le cabinet]. Attendre sa réponse avant tout nouveau contact sur ce dossier.

## Trois points a retenir

1. Opération inhabituelle ou sans logique économique : examen renforcé, questions documentées, aucune opération en attendant.
2. Soupçon : remonter au responsable désigné, par écrit, avec les faits ; la déclaration à Tracfin n'est pas le geste du conseiller seul.
3. Ne jamais informer le client d'un signalement possible, ne jamais avancer « pour voir ».$academy_seed$, $academy_seed${"enonce":"Un client refuse d'expliquer l'origine de 400 000 euros arrivés par virements depuis l'étranger. Quelle est votre première action en sortant du rendez-vous ?","choix":["Prévenir le client qu'un signalement sera fait s'il ne répond pas","Remonter les faits par écrit au responsable désigné, sans exécuter d'opération","Lancer la souscription, l'assureur fera ses propres contrôles","Effectuer vous-même une déclaration à Tracfin depuis votre poste"],"explication":"La leçon décrit le troisième niveau : aucune opération tant que le doute n'est pas levé, remontée écrite et factuelle au responsable désigné. Informer le client est interdit par l'article L561-18, et la déclaration à Tracfin relève de la personne désignée par le cabinet, pas du conseiller seul.","competence":"Reconnaître le besoin d'escalade"}$academy_seed$::jsonb, 1, $academy_seed$[{"titre":"Code monétaire et financier, article L561-10-2 (examen renforcé des opérations complexes ou inhabituelles)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000033517652","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur au 3 décembre 2016","ce_qu_elle_etablit":"Examen renforcé de toute opération particulièrement complexe, d'un montant inhabituellement élevé ou sans justification économique ou objet licite apparent ; le cabinet se renseigne sur l'origine et la destination des fonds, l'objet de l'opération et le bénéficiaire."},{"titre":"Code monétaire et financier, article L561-10 (mesures de vigilance complémentaires)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000041577809","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur au 24 décembre 2025","ce_qu_elle_etablit":"Vigilance complémentaire pour les personnes politiquement exposées, les produits ou opérations favorisant l'anonymat et les opérations avec des pays à haut risque."},{"titre":"Code monétaire et financier, article L561-15 (déclaration de soupçon à Tracfin)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000033517847","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur au 3 décembre 2016","ce_qu_elle_etablit":"Obligation de déclarer les sommes ou opérations dont on sait, soupçonne ou a de bonnes raisons de soupçonner qu'elles proviennent d'une infraction punie de plus d'un an d'emprisonnement, ou de fraude fiscale selon des critères fixés par décret."},{"titre":"Code monétaire et financier, section 4, article L561-18 (confidentialité de la déclaration)","url":"https://www.legifrance.gouv.fr/codes/section_lc/LEGITEXT000006072026/LEGISCTA000020180500/","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur au 1er juin 2019","ce_qu_elle_etablit":"La déclaration à Tracfin est confidentielle ; il est interdit d'en révéler l'existence, le contenu ou les suites au propriétaire des fonds ou à des tiers non autorisés."},{"titre":"Code monétaire et financier, article L561-8 (impossibilité de satisfaire aux obligations d'identification)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000041577826","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur au 14 février 2020","ce_qu_elle_etablit":"Aucune opération et aucune relation d'affaires tant que l'identification et la connaissance de la relation ne sont pas satisfaites ; possibilité de déclaration à Tracfin."},{"titre":"Code monétaire et financier, article R561-23 (désignation des personnes habilitées à déclarer à Tracfin)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000041592391","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur consultée le 2026-09-21","ce_qu_elle_etablit":"Les personnes assujetties, dont les conseillers en investissements financiers, communiquent à Tracfin et à leur autorité de contrôle l'identité de leurs dirigeants ou préposés habilités à procéder aux déclarations de soupçon ; la déclaration relève donc d'une personne habilitée et déclarée, pas d'un conseiller isolé."},{"titre":"FAQ ERMES, plateforme de télédéclaration de Tracfin","url":"https://tracfin.finances.gouv.fr/Pages/Faq.aspx","emetteur":"Tracfin","date_consultation":"2026-09-21","date_validite":"page consultée le 2026-09-21","ce_qu_elle_etablit":"Pour déclarer un soupçon, le professionnel doit préalablement être inscrit sur ERMES en tant que déclarant, ce qui suppose une désignation formelle au sein du cabinet."},{"titre":"Code monétaire et financier, article L574-1 (sanction de la divulgation d'une déclaration de soupçon)","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000041578321","emetteur":"Légifrance","date_consultation":"2026-09-21","date_validite":"version en vigueur consultée le 2026-09-21","ce_qu_elle_etablit":"La méconnaissance de l'interdiction de divulgation posée à l'article L561-18 est punie d'une amende de 22 500 euros."}]$academy_seed$::jsonb)
  returning id into v_l3;
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l1, $academy_seed$q01$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Identifier les pièces manquantes$academy_seed$, $academy_seed$Un client vous a remis toutes les pièces sauf le justificatif d'origine des 150 000 euros qu'il souhaite investir. Il propose de signer aujourd'hui et de vous envoyer l'acte de vente la semaine prochaine. Que faites-vous ?$academy_seed$, $academy_seed$["Signer aujourd'hui et noter la pièce à recevoir dans le CRM","Suspendre la souscription jusqu'à réception de la pièce, tout en poursuivant l'étude","Remplacer la pièce par une attestation sur l'honneur signée du client","Renoncer au dossier, le client cherche à contourner la règle"]$academy_seed$::jsonb, 1)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$La leçon 1 rappelle que l'origine des fonds fait partie des éléments sans lesquels aucune opération n'est exécutée, et qu'une pièce produite après l'opération ne régularise pas le dossier. Rien n'interdit de poursuivre l'analyse en attendant. Une attestation sur l'honneur ne documente pas l'origine, et renoncer serait disproportionné pour un délai d'une semaine.$academy_seed$);
