  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Faux. La leçon 1 cite l'AMF : l'ancienneté de la relation, une connaissance supposée du client ou l'absence apparente de risque ne dispensent pas d'un dossier à jour. La vigilance constante de l'article L561-6 suppose une actualisation régulière et documentée.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l1, $academy_seed$q03$academy_seed$, $academy_seed$cas_court$academy_seed$, $academy_seed$Identifier les pièces manquantes$academy_seed$, $academy_seed$Une SARL souhaite placer sa trésorerie. Le gérant vous remet sa carte d'identité et un extrait d'immatriculation datant de quatorze mois. Que manque-t-il en priorité pour entrer en relation ?$academy_seed$, $academy_seed$["Rien, la pièce d'identité du gérant suffit pour une société","Un extrait d'immatriculation récent et l'identification des bénéficiaires effectifs","Les trois derniers bilans de la société","Le justificatif de domicile personnel du gérant uniquement"]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$La leçon 1 précise que pour une société, le dossier comporte un extrait d'immatriculation récent, les statuts et l'identification des bénéficiaires effectifs, que l'article L561-5 impose d'identifier et de vérifier. La synthèse AMF de juin 2026 cite précisément l'absence d'extrait récent et de documents sur les bénéficiaires effectifs parmi les manquements relevés. Les bilans relèvent de l'étude, pas de l'entrée en relation.$academy_seed$);
