  values (v_ver, v_l2, $academy_seed$q04$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Détecter les incohérences$academy_seed$, $academy_seed$Le questionnaire indique 60 000 euros de revenus annuels, l'avis d'imposition 38 000 euros. Le client veut placer 250 000 euros d'économies. Quelle est la bonne suite ?$academy_seed$, $academy_seed$["Corriger le questionnaire pour l'aligner sur l'avis d'imposition","Ignorer l'écart, il ne change pas la recommandation","Questionner le client sur l'écart et sur l'origine des 250 000 euros, puis noter la réponse et la pièce","Remonter immédiatement le dossier pour déclaration à Tracfin"]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 2, $academy_seed$La leçon 2 décrit la méthode : une incohérence se questionne avec neutralité, la réponse est écrite dans la fiche et appuyée par une pièce. Corriger seul revient à fabriquer le dossier, ignorer contredit la vigilance constante, et une escalade immédiate serait prématurée tant que le client n'a pas été interrogé.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l2, $academy_seed$q05$academy_seed$, $academy_seed$vrai_faux$academy_seed$, $academy_seed$Détecter les incohérences$academy_seed$, $academy_seed$Une incohérence entre le questionnaire et une pièce du dossier signifie que le client cherche à tromper le cabinet.$academy_seed$, $academy_seed$["Vrai","Faux"]$academy_seed$::jsonb, 1)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Faux. La leçon 2 rappelle qu'une incohérence est le plus souvent une erreur de saisie, un oubli ou une information dépassée. Elle n'est pas une accusation, mais elle doit être questionnée et résolue par écrit avant toute recommandation.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l2, $academy_seed$q06$academy_seed$, $academy_seed$cas_court$academy_seed$, $academy_seed$Détecter les incohérences$academy_seed$, $academy_seed$Un client déclare un horizon de quinze ans pour « préparer la retraite », puis évoque un achat immobilier dans dix-huit mois qui mobilisera la majeure partie de la somme à placer. Quelle incohérence traitez-vous en priorité et avec quelle conséquence ?$academy_seed$, $academy_seed$["Le profil de risque doit être relevé pour tenir les deux objectifs","L'horizon et le besoin de liquidité contredisent l'objectif : réinterroger le client avant toute recommandation d'enveloppe peu disponible","Aucune : deux projets différents peuvent coexister sans conséquence","Proposer un PER pour la retraite et conserver le reste sur le compte courant"]$academy_seed$::jsonb, 3)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$La leçon 2 cite ce croisement parmi les quatre à faire systématiquement : horizon et objectif contre besoin de liquidité. Tant que le client n'a pas clarifié ce qu'il pourra réellement immobiliser, aucune enveloppe à liquidité contrainte ne peut être recommandée. Relever le risque ou proposer une solution avant d'avoir résolu l'écart inverse la méthode.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l3, $academy_seed$q07$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Reconnaître le besoin d'escalade$academy_seed$, $academy_seed$Un client souhaite verser 400 000 euros depuis deux banques dont une à l'étranger et refuse d'expliquer l'origine des fonds. Que faites-vous ?$academy_seed$, $academy_seed$["Avancer, la compagnie d'assurance fera ses propres contrôles","Effectuer vous-même une déclaration à Tracfin depuis votre poste","Ne rien faire signer et remonter les faits par écrit au responsable désigné","Informer le client qu'un signalement sera fait s'il ne fournit pas la pièce"]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 2, $academy_seed$La leçon 3 décrit le circuit : aucune opération tant que le doute n'est pas levé, remontée écrite et factuelle au responsable désigné. L'obligation du cabinet ne se délègue pas à la compagnie, la déclaration relève de la personne désignée en interne, et informer le client est interdit par l'article L561-18.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l3, $academy_seed$q08$academy_seed$, $academy_seed$vrai_faux$academy_seed$, $academy_seed$Reconnaître le besoin d'escalade$academy_seed$, $academy_seed$Par souci de transparence, le conseiller doit prévenir le client qu'une déclaration de soupçon a été effectuée à son sujet.$academy_seed$, $academy_seed$["Vrai","Faux"]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Faux. La leçon 3 rappelle que la déclaration à Tracfin est confidentielle et que l'article L561-18 interdit d'en révéler l'existence, le contenu ou les suites au client ou à un tiers. La transparence invoquée est ici une infraction.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l3, $academy_seed$q09$academy_seed$, $academy_seed$cas_court$academy_seed$, $academy_seed$Reconnaître le besoin d'escalade$academy_seed$, $academy_seed$Un client connu du cabinet, coopératif, souhaite réaliser une opération d'un montant très supérieur à tout ce que son dossier laissait attendre, sans logique économique apparente. Que demande la loi au cabinet ?$academy_seed$, $academy_seed$["Refuser l'opération d'office","Réaliser un examen renforcé : se renseigner sur l'origine et la destination des fonds, l'objet de l'opération et son bénéficiaire, et documenter les réponses","Ne rien faire de particulier, le client est connu et coopératif","Effectuer automatiquement une déclaration de soupçon"]$academy_seed$::jsonb, 3)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$La leçon 3 présente le deuxième niveau de réaction : l'article L561-10-2 impose un examen renforcé de toute opération d'un montant inhabituellement élevé ou sans justification économique apparente. Ce n'est ni un refus automatique ni une déclaration automatique ; c'est une phase de questions documentées, à l'issue de laquelle le dossier avance, se suspend ou s'escalade.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l1, $academy_seed$q10$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Identifier les pièces manquantes$academy_seed$, $academy_seed$Une cliente explique que les 180 000 euros à investir proviennent de la vente d'un appartement. Quel ensemble de pièces documente le mieux cette origine des fonds ?$academy_seed$, $academy_seed$["Une attestation sur l'honneur rédigée par la cliente","Un relevé de compte montrant le solde actuel","L'acte ou l'attestation notariée de vente, avec le relevé montrant l'arrivée des fonds","Le dernier avis d'imposition"]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 2, $academy_seed$La leçon 1 rappelle que le dossier prouve, il ne raconte pas : l'origine des fonds s'appuie sur une pièce qui établit l'événement (la vente) et une pièce qui relie cet événement aux sommes (le virement reçu). Un solde, une attestation sur l'honneur ou un avis d'imposition ne montrent pas d'où vient l'argent.$academy_seed$);
end
$seed_qualite_du_dossier$;
